const ID_PATTERN = /^[a-z0-9][a-z0-9-]{1,39}$/;
const MAX_PORT_STRIDE = 10;
const FIELD_TYPES = new Set(['select', 'text', 'secret', 'number', 'toggle', 'custom']);
const CONFIG_FORMATS = new Set<ConfigFormat>(['properties', 'ini', 'json', 'toml', 'lines']);

const isObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const isLocalized = (value: unknown): boolean =>
  typeof value === 'string' ||
  (isObject(value) && Object.values(value).every((entry) => typeof entry === 'string'));

const isStringList = (value: unknown): boolean =>
  Array.isArray(value) && value.every((item) => typeof item === 'string');

const isPlatformValue = (value: unknown): boolean =>
  typeof value === 'string' ||
  (isObject(value) && Object.values(value).every((entry) => typeof entry === 'string'));

const isSafeRelativePath = (value: unknown): boolean =>
  typeof value === 'string' &&
  value.length > 0 &&
  !value.startsWith('/') &&
  !/^[a-zA-Z]:/.test(value) &&
  !value.split(/[\\/]/).includes('..');

const checkPatterns = (label: string, value: unknown, errors: string[]): void => {
  if (value === undefined) return;
  const list = typeof value === 'string' ? [value] : value;
  if (!isStringList(list)) {
    errors.push(`${label} must be a regular expression string or a list of strings`);
    return;
  }
  for (const pattern of list as string[]) {
    try {
      new RegExp(pattern, 'i');
    } catch {
      errors.push(`${label} contains an invalid regular expression: ${pattern}`);
    }
  }
};

/** Validates untrusted JSON against the manifest contract and returns every problem found. */
export function validateManifest(raw: unknown): ManifestValidation {
  const errors: string[] = [];
  if (!isObject(raw)) return { ok: false, errors: ['The manifest must be a JSON object'] };

  if (raw.apiVersion !== GAME_PACK_API_VERSION) {
    errors.push(`apiVersion must be ${GAME_PACK_API_VERSION} (got ${JSON.stringify(raw.apiVersion)})`);
  }
  if (typeof raw.id !== 'string' || !ID_PATTERN.test(raw.id)) {
    errors.push('id must be 2-40 chars of lowercase letters, digits and dashes');
  }
  if (typeof raw.name !== 'string' || !raw.name.trim()) errors.push('name is required');
  if (typeof raw.version !== 'string' || !raw.version.trim()) errors.push('version is required');
  if (raw.logo !== undefined && !isSafeRelativePath(raw.logo)) errors.push('logo must be a relative path inside the pack');
  if (raw.description !== undefined && !isLocalized(raw.description)) errors.push('description must be text or a language map');
  if (raw.status !== undefined && !['available', 'beta', 'coming_soon'].includes(String(raw.status))) {
    errors.push('status must be available, beta or coming_soon');
  }

  const defaults = raw.defaults;
  if (
    !isObject(defaults) ||
    !Number.isInteger(defaults.port) ||
    (defaults.port as number) < 1 ||
    (defaults.port as number) > 65535 ||
    !Number.isInteger(defaults.maxPlayers) ||
    (defaults.maxPlayers as number) < 1
  ) {
    errors.push('defaults.port (1-65535) and defaults.maxPlayers (>= 1) are required integers');
  }
  if (
    isObject(defaults) &&
    defaults.portStride !== undefined &&
    (!Number.isInteger(defaults.portStride) || (defaults.portStride as number) < 1 || (defaults.portStride as number) > MAX_PORT_STRIDE)
  ) {
    errors.push(`defaults.portStride must be an integer between 1 and ${MAX_PORT_STRIDE}`);
  }

  const launch = raw.launch;
  if (!isObject(launch) || !isPlatformValue(launch.executable) || launch.executable === '') {
    errors.push('launch.executable is required');
  } else {
    if (launch.args !== undefined && !isStringList(launch.args)) errors.push('launch.args must be a list of strings');
    if (launch.runtime !== undefined && !['native', 'java'].includes(String(launch.runtime))) {
      errors.push('launch.runtime must be native or java');
    }
  }

  if (isObject(launch) && launch.discover !== undefined) {
    const discover = launch.discover;
    const argOk = (arg: unknown) =>
      typeof arg === 'string' ||
      (isObject(arg) && typeof arg.arg === 'string' && isSafeRelativePath(arg.ifExists));
    if (
      !Array.isArray(discover) ||
      !discover.every(
        (entry) =>
          isObject(entry) &&
          isSafeRelativePath(entry.glob) &&
          (entry.platform === undefined || ['win32', 'linux', 'darwin'].includes(String(entry.platform))) &&
          (entry.mode === undefined || ['args', 'jar'].includes(String(entry.mode))) &&
          (entry.args === undefined || (Array.isArray(entry.args) && entry.args.every(argOk))) &&
          (entry.variants === undefined ||
            (Array.isArray(entry.variants) && entry.variants.every((variant) => typeof variant === 'string' && variant !== '')))
      )
    ) {
      errors.push('launch.discover must be a list of { glob (relative), platform?, exclude?, mode?, args?, variants? }');
    } else {
      for (const entry of discover as Array<Record<string, unknown>>) {
        if (entry.exclude !== undefined) checkPatterns('launch.discover.exclude', entry.exclude, errors);
      }
    }
  }

  if (raw.playerActions !== undefined) {
    const actions = raw.playerActions;
    const paramOk = (param: unknown) =>
      isObject(param) &&
      typeof param.id === 'string' &&
      isLocalized(param.label) &&
      ['text', 'number', 'select'].includes(String(param.type));
    if (
      !Array.isArray(actions) ||
      !actions.every(
        (action) =>
          isObject(action) &&
          typeof action.id === 'string' &&
          isLocalized(action.label) &&
          (typeof action.command === 'string' ||
            (isStringList(action.command) && (action.command as string[]).length > 0) ||
            (action.command === undefined && typeof action.bridgeAction === 'string')) &&
          (action.bridgeAction === undefined || typeof action.bridgeAction === 'string') &&
          (action.icon === undefined || typeof action.icon === 'string') &&
          (action.quick === undefined || typeof action.quick === 'boolean') &&
          (action.params === undefined || (Array.isArray(action.params) && action.params.every(paramOk)))
      )
    ) {
      errors.push('playerActions must be a list of { id, label, command (text or list) and/or bridgeAction, params?, quick?, icon? }');
    }
  }

  if (raw.devMock !== undefined && !isSafeRelativePath(raw.devMock)) errors.push('devMock must be a relative path inside the pack');

  if (raw.motd !== undefined) {
    const motd = raw.motd;
    if (
      !isObject(motd) ||
      (motd.colorCodes !== undefined && typeof motd.colorCodes !== 'boolean') ||
      (motd.preview !== undefined && typeof motd.preview !== 'boolean')
    ) {
      errors.push('motd must be { colorCodes?: boolean, preview?: boolean }');
    }
  }

  if (raw.installer !== undefined) {
    const installer = raw.installer;
    const variantOk = (variant: unknown) =>
      isObject(variant) &&
      typeof variant.id === 'string' &&
      typeof variant.name === 'string' &&
      typeof variant.automatic === 'boolean' &&
      (variant.group === undefined || isLocalized(variant.group)) &&
      (variant.url === undefined || typeof variant.url === 'string');
    const java = isObject(installer) ? installer.javaRequirements : undefined;
    if (
      !isObject(installer) ||
      !Array.isArray(installer.variants) ||
      installer.variants.length === 0 ||
      !installer.variants.every(variantOk) ||
      (installer.fileTypes !== undefined && !isStringList(installer.fileTypes)) ||
      (java !== undefined &&
        (!isObject(java) ||
          typeof java.default !== 'number' ||
          !Array.isArray(java.versions) ||
          !java.versions.every((entry) => isObject(entry) && typeof entry.from === 'string' && typeof entry.java === 'number')))
    ) {
      errors.push('installer must be { variants: [{ id, name, automatic, group?, url? }], defaultVariant?, fileTypes?, javaRequirements? }');
    }
  }

  if (raw.performance !== undefined) {
    const performance = raw.performance;
    if (!isObject(performance) || typeof performance.tickRate !== 'number' || performance.tickRate <= 0) {
      errors.push('performance must be { tickRate (> 0) }');
    }
  }

  if (raw.dimensions !== undefined) {
    const dimensions = raw.dimensions;
    if (
      !Array.isArray(dimensions) ||
      !dimensions.every(
        (dimension) =>
          isObject(dimension) &&
          typeof dimension.id === 'string' &&
          isLocalized(dimension.label) &&
          (dimension.aliases === undefined || isStringList(dimension.aliases)) &&
          (dimension.icon === undefined || isSafeRelativePath(dimension.icon))
      )
    ) {
      errors.push('dimensions must be a list of { id, label, aliases?, icon? (relative path) }');
    }
  }

  if (raw.instanceFolders !== undefined) {
    if (!isStringList(raw.instanceFolders) || !(raw.instanceFolders as string[]).every(isSafeRelativePath)) {
      errors.push('instanceFolders must be a list of relative folder names');
    }
  }
  if (raw.modLayout !== undefined) {
    const layout = raw.modLayout;
    if (
      !isObject(layout) ||
      (layout.modsDir !== undefined && !isSafeRelativePath(layout.modsDir)) ||
      (layout.configDir !== undefined && !isSafeRelativePath(layout.configDir)) ||
      (layout.fileTypes !== undefined && !isStringList(layout.fileTypes))
    ) {
      errors.push('modLayout must be { modsDir?, configDir?, fileTypes? } with relative paths');
    }
  }
  if (raw.bridgeTargets !== undefined) {
    const targets = raw.bridgeTargets;
    if (
      !isObject(targets) ||
      !Object.values(targets).every(
        (target) => isObject(target) && isSafeRelativePath(target.dir) && isSafeRelativePath(target.asset)
      )
    ) {
      errors.push('bridgeTargets must map loaders to { dir, asset } with relative paths');
    }
  }

  if (raw.creationSettings !== undefined) {
    const settings = raw.creationSettings;
    if (
      !Array.isArray(settings) ||
      !settings.every(
        (setting) =>
          isObject(setting) &&
          typeof setting.id === 'string' &&
          isLocalized(setting.label) &&
          ['select', 'text', 'number'].includes(String(setting.type)) &&
          isSafeRelativePath(setting.file) &&
          typeof setting.key === 'string'
      )
    ) {
      errors.push('creationSettings must be a list of { id, label, type, file (relative), key }');
    }
  }

  if (raw.quickCommands !== undefined) {
    const quick = raw.quickCommands;
    if (
      !Array.isArray(quick) ||
      !quick.every((item) => isObject(item) && typeof item.label === 'string' && typeof item.command === 'string')
    ) {
      errors.push('quickCommands must be a list of { label, command }');
    }
  }

  if (raw.playerLists !== undefined) {
    const lists = raw.playerLists;
    const listIds = new Set<string>();
    const commandOk = (value: unknown) => typeof value === 'string' && value.includes('{{value}}');
    const listOk = (list: unknown): boolean => {
      if (!isObject(list) || typeof list.id !== 'string' || !ID_PATTERN.test(list.id) || listIds.has(list.id)) return false;
      listIds.add(list.id);
      const toggle = list.toggle;
      return (
        isLocalized(list.label) &&
        (list.description === undefined || isLocalized(list.description)) &&
        (list.icon === undefined || typeof list.icon === 'string') &&
        isSafeRelativePath(list.file) &&
        typeof list.key === 'string' &&
        list.key !== '' &&
        (list.details === undefined || (Array.isArray(list.details) && list.details.every((field) => typeof field === 'string'))) &&
        (list.valueType === undefined || list.valueType === 'player' || list.valueType === 'ip') &&
        commandOk(list.add) &&
        commandOk(list.remove) &&
        (list.reason === undefined || typeof list.reason === 'boolean') &&
        (toggle === undefined ||
          (isObject(toggle) &&
            isSafeRelativePath(toggle.configFile) &&
            typeof toggle.key === 'string' &&
            typeof toggle.on === 'string' &&
            typeof toggle.off === 'string'))
      );
    };
    if (!Array.isArray(lists) || !lists.every(listOk)) {
      errors.push(
        'playerLists must be a list of { id (unique), label, file (relative), key, add and remove (with {{value}}), description?, icon?, details?, valueType?, reason?, toggle? }'
      );
    }
  }

  if (raw.playerView !== undefined && !isObject(raw.playerView)) errors.push('playerView must be an object');

  if (raw.playerQueries !== undefined) {
    const queries = raw.playerQueries;
    if (
      !Array.isArray(queries) ||
      !queries.every(
        (query) =>
          isObject(query) &&
          typeof query.id === 'string' &&
          typeof query.command === 'string' &&
          typeof query.pattern === 'string' &&
          isObject(query.fields) &&
          Object.values(query.fields).every((kind) => kind === 'number' || kind === 'string')
      )
    ) {
      errors.push('playerQueries must be a list of { id, command, pattern, fields }');
    } else {
      for (const query of queries as Array<Record<string, unknown>>) {
        checkPatterns(`playerQueries.${String(query.id)}.pattern`, query.pattern, errors);
        if (typeof query.pattern === 'string' && !query.pattern.includes('(?<username>')) {
          errors.push(`playerQueries.${String(query.id)}.pattern must define the named group "username"`);
        }
      }
    }
  }

  if (raw.configSync !== undefined) {
    const sync = raw.configSync;
    if (!isObject(sync) || !isSafeRelativePath(sync.file) || !['properties', 'ini', 'json', 'toml'].includes(String(sync.format)) || !isObject(sync.map)) {
      errors.push('configSync must be { file (relative), format (properties|ini|json|toml), map }');
    }
  }

  if (raw.serverIcon !== undefined) {
    const icon = raw.serverIcon;
    if (
      !isObject(icon) ||
      !isSafeRelativePath(icon.file) ||
      !String(icon.file).toLowerCase().endsWith('.png') ||
      !Number.isInteger(icon.size) ||
      (icon.size as number) < 16 ||
      (icon.size as number) > 1024
    ) {
      errors.push('serverIcon must be { file (relative .png), size (16-1024) }');
    }
  }
  if (raw.backup !== undefined) {
    const backup = raw.backup;
    if (!isObject(backup) || !Array.isArray(backup.paths) || !backup.paths.every(isSafeRelativePath)) {
      errors.push('backup must be { paths: list of relative paths }');
    }
  }
  if (raw.bridgeLoaders !== undefined && !isStringList(raw.bridgeLoaders)) {
    errors.push('bridgeLoaders must be a list of strings');
  }

  if (raw.provision !== undefined) {
    const provision = raw.provision;
    const valid =
      isObject(provision) &&
      (provision.type === 'none' ||
        (provision.type === 'steamcmd' &&
          Number.isInteger(provision.appId) &&
          (provision.branchField === undefined || typeof provision.branchField === 'string')) ||
        (provision.type === 'download' &&
          typeof provision.url === 'string' &&
          /^https:\/\//i.test(provision.url) &&
          (provision.filename === undefined || typeof provision.filename === 'string') &&
          (provision.sha256 === undefined || /^[a-f0-9]{64}$/i.test(String(provision.sha256)))));
    if (!valid) {
      errors.push(
        'provision must be { "type": "none" }, { "type": "steamcmd", "appId": <number> } or { "type": "download", "url": "https://...", "sha256"?: <hex> }'
      );
    }
  }

  if (raw.detect !== undefined && !(isStringList(raw.detect) && (raw.detect as string[]).every(isSafeRelativePath))) {
    errors.push('detect must be a list of relative file paths');
  }

  if (raw.logs !== undefined) {
    if (!isObject(raw.logs)) {
      errors.push('logs must be an object');
    } else {
      checkPatterns('logs.ready', raw.logs.ready, errors);
      checkPatterns('logs.join', raw.logs.join, errors);
      checkPatterns('logs.leave', raw.logs.leave, errors);
      if (raw.logs.dimension !== undefined && typeof raw.logs.dimension !== 'string') errors.push('logs.dimension must be a string');
    }
  }

  if (raw.configFiles !== undefined) {
    const files = raw.configFiles;
    if (
      !Array.isArray(files) ||
      !files.every((file) => isObject(file) && isSafeRelativePath(file.path) && CONFIG_FORMATS.has(file.format as ConfigFormat))
    ) {
      errors.push('configFiles must be a list of { path (relative), format (properties|ini|json|toml|lines) }');
    }
  }

  if (raw.setup !== undefined) {
    const fields = raw.setup;
    if (
      !Array.isArray(fields) ||
      !fields.every(
        (field) =>
          isObject(field) && typeof field.id === 'string' && FIELD_TYPES.has(String(field.type)) && isLocalized(field.label)
      )
    ) {
      errors.push('setup must be a list of { id, type, label }');
    }
  }

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, errors: [], manifest: raw as unknown as GameManifest };
}
